# owner: platform
import unittest

from hourglass.models import Span
from hourglass.gaps import uncovered_gaps

class GapTests(unittest.TestCase):
    def test_gaps_inside_and_at_edges(self):
        worked = [Span(600, 720), Span(780, 840)]
        self.assertEqual(
            uncovered_gaps(worked, Span(540, 900)),
            [
                "gap 09:00-10:00 (60 min)",
                "gap 12:00-13:00 (60 min)",
                "gap 14:00-15:00 (60 min)"
            ]
        )

    def test_full_cover_has_no_gaps(self):
        worked = [Span(540, 700), Span(600, 900)]
        self.assertEqual(
            uncovered_gaps(worked, Span(540, 900)), []
        )

    def test_nobody_working(self):
        self.assertEqual(
            uncovered_gaps([], Span(540, 600)),
            ["gap 09:00-10:00 (60 min)"]
        )

    def test_span_outside_opening_raises(self):
        with self.assertRaises(ValueError):
            uncovered_gaps([Span(500, 600)], Span(540, 900))
